const runtime=runtimeConfig();
const app=express();app.disable('x-powered-by');if(runtime.production)app.set('trust proxy',1);app.use(compression());app.use(express.json({limit:'5mb'}));
const PORT=Number(process.env.PORT||4310);const spec=JSON.parse(await fs.readFile('src/workbook.json','utf8'));
