const tenderInput=raw=>Object.fromEntries(Object.entries(raw||{}).filter(([k])=>spec.fields.some(f=>f.key===k&&!f.computed&&!['approvedBy','decisionDate'].includes(k))||['timezone','noGoReason'].includes(k)));
const sha=x=>createHash('sha256').update(x).digest('hex');const fail=(status,message)=>Object.assign(new Error(message),{status});
const cleanUser=u=>({id:u.id,name:u.name,email:u.bdms_id?(u.contact_email||''):u.email,roles:u.roles,businessUnit:u.business_unit,active:u.active,phone:u.phone,bdmsId:u.bdms_id,login:u.bdms_login,tenderPermissions:u.tender_permissions});
function sessionDetails(req){return {ipAddress:req.ip,deviceId:String(req.headers['x-device-id']||'').slice(0,80),userAgent:String(req.headers['user-agent']||'').slice(0,500)};}
function cookie(req){return (req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('tt_session='))?.slice(11);}
const attempts=new Map();
const ssoReady=installOidc(app,pool,audit);
app.use('/api',(req,res,next)=>{res.set('Cache-Control','no-store');if(['POST','PUT','PATCH','DELETE'].includes(req.method)&&req.headers.origin){const origin=new URL(req.headers.origin);if(runtime.production?origin.origin!==runtime.publicOrigin:origin.host!==req.headers.host)return next(fail(403,'Request origin is not allowed.'));}next();});
app.get('/api/health',async(req,res)=>{const r=await pool.query('SELECT version()');res.json({status:'ok',database:'PostgreSQL',version:r.rows[0].version,serverTime:new Date().toISOString()});});
app.post('/api/login',async(req,res)=>{const ip=req.ip;const attempt=attempts.get(ip)||{count:0,start:Date.now()};if(Date.now()-attempt.start>900000){attempt.count=0;attempt.start=Date.now();}if(++attempt.count>30)throw fail(429,'Too many sign-in attempts. Try again in 15 minutes.');attempts.set(ip,attempt);let profile;let u;if(bdmsEnabled()){profile=await identityRequest('authenticate',{username:req.body.username||req.body.email,password:req.body.password,details:sessionDetails(req)});u=await projectIdentity(pool,profile);}else{u=(await pool.query('SELECT * FROM users WHERE lower(email)=lower($1) AND active=true',[String(req.body.email||'')])).rows[0];if(!u)throw fail(401,'Email or password is incorrect.');const [salt,hash]=u.password_hash.split(':');const input=scryptSync(String(req.body.password||''),salt,64);if(!timingSafeEqual(input,Buffer.from(hash,'hex')))throw fail(401,'Email or password is incorrect.');}attempts.delete(ip);const token=randomBytes(32).toString('hex');await pool.query("INSERT INTO sessions(token_hash,user_id,expires_at,credential_version,bdms_session_id) VALUES($1,$2,now()+interval '30 days',$3,$4)",[sha(token),u.id,profile?.credentialVersion||null,profile?.sessionId||null]);res.cookie('tt_session',token,{httpOnly:true,sameSite:'strict',maxAge:2592000000,secure:runtime.production,path:'/'});await audit(pool,u,null,'Signed in','session',{},{});res.json(cleanUser(u));});
app.use('/api',async(req,res,next)=>{if(['/health','/login','/logout'].includes(req.path))return next();const token=cookie(req);if(!token)return next(fail(401,'Please sign in.'));const r=await pool.query('SELECT u.*,s.credential_version,s.bdms_session_id FROM sessions s JOIN users u ON u.id=s.user_id WHERE token_hash=$1 AND expires_at>now() AND u.active=true',[sha(token)]);if(!r.rowCount)return next(fail(401,'Your session has expired.'));let user=r.rows[0];if(bdmsEnabled()){if(!user.bdms_id||!user.credential_version||!user.bdms_session_id)throw fail(401,'Please sign in with your BDMS account.');try{const profile=await identityRequest('validate',{id:user.bdms_id,credentialVersion:user.credential_version,sessionId:user.bdms_session_id,details:sessionDetails(req)});req.bdmsSession={id:user.bdms_id,credentialVersion:user.credential_version,sessionId:user.bdms_session_id};user=await projectIdentity(pool,profile);}catch(error){if([401,403].includes(error.status)){await pool.query('DELETE FROM sessions WHERE token_hash=$1',[sha(token)]);error.status=401;}throw error;}}req.user={...cleanUser(user),permissionView:req.headers['x-mobile']==='true'?'mobile':'desktop'};req.settings=await settings();next();});
app.use('/api',(req,res,next)=>{const p=req.path;if(p.startsWith('/admin/')&&!req.user.roles.includes('System Administrator'))return next(fail(403,'Administrator access required.'));if(!req.user?.tenderPermissions)return next();let key=null;if(p.startsWith('/admin/')){const section=p.split('/')[2];key='admin.'+({deliveries:'integrations','run-reminders':'integrations',restore:'backup',settings:'workflow'}[section]||section);if(section==='settings'){const changed=Object.keys(req.body||{}).filter(k=>JSON.stringify(req.body[k])!==JSON.stringify(req.settings[k]));if(changed.some(k=>k==='permissions'||k==='approvers')&&!tenderAllowed(req.user,'admin.access'))return next(fail(403,'Tender permission settings are restricted.'));if(changed.some(k=>!['permissions','approvers'].includes(k))&&!tenderAllowed(req.user,'admin.workflow'))return next(fail(403,'Tender workflow settings are restricted.'));return next();}}else if(p.startsWith('/import')){if(!permitted(req.user,'overview','write',req.settings))return next(fail(403,'Tender creation access required.'));}else if(p.startsWith('/portal'))key='menu.portal';else if(p.startsWith('/notifications'))key='menu.notifications';else if(p.startsWith('/approvals'))key='menu.approvals';else if(p.startsWith('/documents'))key='documents.read';else if(p==='/audit')key=req.query.tenderId?'audit.read':'admin.audit';if(key&&!tenderAllowed(req.user,key))return next(fail(403,'This Tender feature is not assigned to your BDMS user.'));if((p==='/tenders'||p==='/export'||(/^\/tenders\/[^/]+$/.test(p)&&req.method==='GET'))&&!tenderCanList(req.user))return next(fail(403,'Tender record access is not assigned.'));next();});
const isAdmin=req=>req.user.roles.includes('System Administrator')&&tenderAdministration(req.user);
const guard=(req,module,action='write')=>{if(!permitted(req.user,module,action,req.settings))throw fail(403,'Your role does not have permission for this action.');};
function sanitizeRecord(req,r){const copy=structuredClone(r);if(!canSeePricing(req.user)||(!req.user.tenderPermissions&&req.headers['x-mobile']==='true'))for(const k of pricingFields)delete copy.data[k];return copy;}
function sanitizeAudit(req,row){const copy=structuredClone(row);if(!canSeePricing(req.user)||(!req.user.tenderPermissions&&req.headers['x-mobile']==='true'))for(const k of pricingFields)delete copy.changes?.[k];return copy;}
async function getTender(req,id,c=pool,lock=false){const r=await c.query(`SELECT * FROM tenders WHERE id=$1 ${lock?'FOR UPDATE':''}`,[id]);if(!r.rowCount)throw fail(404,'Tender was not found.');const t=r.rows[0];if(t.draft&&t.creator!==req.user.id&&!isAdmin(req))throw fail(403,'Drafts are private to their creator.');if(req.user.businessUnit&&t.data.businessUnit!==req.user.businessUnit&&(!isAdmin(req)||req.user.tenderPermissions))throw fail(403,'This tender belongs to another business unit.');return t;}
async function recordsFor(id,c=pool){const records=(await c.query('SELECT * FROM records WHERE tender_id=$1 ORDER BY created_at',[id])).rows;const docs=(await c.query('SELECT * FROM documents WHERE tender_id=$1 ORDER BY type,version DESC',[id])).rows;return {records,documents:docs,calcRecords:[...records,...docs.map(d=>({module:'documents',data:{type:d.type}}))]};}
function visibleTender(req,t){if(!req.user.tenderPermissions||tenderAllowed(req.user,'overview','read'))return t;const allowed=['title','client','sector','businessUnit','owner','priority','deadline','submissionTime','timezone','currency','region','location'];return {...t,data:Object.fromEntries(Object.entries(t.data).filter(([key])=>allowed.includes(key)))};}
async function listTenders(req){const all=(await pool.query('SELECT * FROM tenders ORDER BY updated_at DESC')).rows.filter(t=>(!t.draft||t.creator===req.user.id||isAdmin(req))&&(!req.user.businessUnit||(isAdmin(req)&&!req.user.tenderPermissions)||t.data.businessUnit===req.user.businessUnit));const ids=all.map(t=>t.id);const allRecords=(await pool.query('SELECT tender_id,module,data FROM records WHERE tender_id=ANY($1::uuid[])',[ids])).rows;const docs=(await pool.query('SELECT tender_id,type FROM documents WHERE tender_id=ANY($1::uuid[])',[ids])).rows;const recordsByTender=new Map(),docsByTender=new Map();for(const r of allRecords){if(!recordsByTender.has(r.tender_id))recordsByTender.set(r.tender_id,[]);recordsByTender.get(r.tender_id).push(r);}for(const d of docs){if(!docsByTender.has(d.tender_id))docsByTender.set(d.tender_id,[]);docsByTender.get(d.tender_id).push({module:'documents',data:{type:d.type}});}return all.map(t=>{const records=recordsByTender.get(t.id)||[];return {...visibleTender(req,t),calculated:classify(t,[...records,...(docsByTender.get(t.id)||[])],req.settings),submission:tenderAllowed(req.user,'submission','read')?sanitizeRecord(req,{data:records.find(r=>r.module==='submission')?.data||{}}).data:{},evaluation:tenderAllowed(req.user,'evaluation','read')?sanitizeRecord(req,{data:records.find(r=>r.module==='evaluation')?.data||{}}).data:{},award:tenderAllowed(req.user,'award','read')?records.find(r=>r.module==='award')?.data||{}:{}};});}
app.get('/api/session/messages',async(req,res)=>{const profile=req.bdmsSession?await identityRequest('messages',{...req.bdmsSession,details:sessionDetails(req)}):{};res.json({messages:profile.messages||[]});});
