app.get('/api/export',async(req,res)=>{const all=(await listTenders(req)).filter(t=>!t.draft);let rows=all;if(req.query.scope==='pending')rows=rows.filter(t=>t.calculated.status==='Pending');if(req.query.scope==='applied'||req.query.scope==='results')rows=rows.filter(t=>t.calculated.status==='Applied');if(req.query.scope==='not-applied')rows=rows.filter(t=>t.calculated.status==='Not Applied');if(req.query.search)rows=rows.filter(t=>[t.tender_id,t.data.title,t.data.client].join(' ').toLowerCase().includes(req.query.search.toLowerCase()));for(const [query,key]of [['sector','sector'],['owner','owner'],['priority','priority'],['businessUnit','businessUnit'],['currency','currency']])if(req.query[query])rows=rows.filter(t=>t.data[key]===req.query[query]);const w=new ExcelJS.Workbook();const sheet=w.addWorksheet('Tender report');sheet.addRow(['Tender ID','Title','Client','Sector','Business unit','Owner','Priority','Currency','Estimated value','Deadline','Status','Reason','Award category','Awarded value','LOA / Work order','Winning bidder','Loss reason']);rows.forEach(t=>sheet.addRow([t.tender_id,t.data.title,t.data.client,t.data.sector,t.data.businessUnit,t.data.owner,t.data.priority,t.data.currency,Number(t.data.estimatedValue||0),t.data.deadline,t.calculated.status,t.calculated.notAppliedReason,t.calculated.awardCategory,t.award.approvalStatus==='Approved'?Number(t.award.awardedValue||0):null,t.award.loaNumber,t.award.winningBidder,t.award.lossReason]));sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF142E37'}};sheet.columns.forEach((c,i)=>c.width=i===1?50:22);sheet.views=[{state:'frozen',ySplit:1}];sheet.autoFilter={from:'A1',to:'Q1'};res.setHeader('Content-Disposition','attachment; filename="tender-report.xlsx"');await w.xlsx.write(res);res.end();});
app.get('/api/admin/backup',async(req,res)=>{if(!isAdmin(req))throw fail(403,'Administrator access required.');const backup={version:1,createdAt:new Date().toISOString(),tables:{}};await transaction(async c=>{await c.query('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');for(const table of ['users','masters','settings','tenders','records','documents','approvals','audit','notifications','deliveries','portal_feed']){const rows=(await c.query(`SELECT * FROM ${table}`)).rows;backup.tables[table]=rows;if(table==='documents')for(const d of rows)d.content=(await fs.readFile(d.stored_path)).toString('base64');}});res.attachment('tender-backup-'+new Date().toISOString().slice(0,10)+'.json');res.json(backup);});
app.post('/api/admin/restore',restoreUpload.single('file'),async(req,res)=>{if(bdmsEnabled())throw fail(403,'Contact your administrator for a data restore; BDMS identities must be preserved.');if(!isAdmin(req))throw fail(403,'Administrator access required.');if(!req.file)throw fail(422,'Choose a backup.');const b=JSON.parse(req.file.buffer.toString('utf8'));if(b.version!==1||!b.tables?.tenders)throw fail(422,'Invalid backup format.');const count=Number((await pool.query('SELECT count(*) FROM tenders')).rows[0].count);if(count)throw fail(409,'Restore requires an empty tender database to avoid overwriting your records.');const allowed=['users','masters','settings','tenders','records','documents','approvals','audit','notifications','deliveries','portal_feed'];const writes=[];try{await transaction(async c=>{const userMap=new Map();for(const user of b.tables.users||[]){const existing=(await c.query('SELECT id FROM users WHERE lower(email)=lower($1)',[user.email])).rows[0];userMap.set(user.id,existing?.id||user.id);}for(const table of allowed){for(const item of b.tables[table]||[]){const row={...item};if(table==='users'&&userMap.get(row.id)!==row.id)continue;for(const key of ['creator','actor','user_id','created_by','uploaded_by','requested_by','decided_by'])if(row[key]&&userMap.has(row[key]))row[key]=userMap.get(row[key]);if(table==='audit')delete row.id;if(table==='documents'){const ext=path.extname(row.filename).toLowerCase();if(!['.pdf','.doc','.docx','.xls','.xlsx','.ppt','.pptx','.jpg','.jpeg','.png','.zip'].includes(ext))throw fail(422,'Invalid document filename.');const target=path.join(fileRoot,randomUUID()+ext);await fs.writeFile(target,Buffer.from(row.content,'base64'));writes.push(target);row.stored_path=target;delete row.content;}const cols=Object.keys(row);const actual=(await c.query('SELECT column_name FROM information_schema.columns WHERE table_schema=\'public\' AND table_name=$1',[table])).rows.map(x=>x.column_name);if(cols.some(k=>!actual.includes(k)))throw fail(422,'Invalid backup columns.');const vals=cols.map(k=>row[k]&&typeof row[k]==='object'?JSON.stringify(row[k]):row[k]);let conflict='ON CONFLICT DO NOTHING';if(table==='settings')conflict='ON CONFLICT(id) DO UPDATE SET data=EXCLUDED.data';if(table==='masters')conflict='ON CONFLICT(list,code) DO UPDATE SET value=EXCLUDED.value,active=EXCLUDED.active';await c.query(`INSERT INTO ${table} (${cols.map(k=>'"'+k+'"').join(',')}) VALUES(${cols.map((_,i)=>'$'+(i+1)).join(',')}) ${conflict}`,vals);}}await c.query("SELECT setval('audit_id_seq',GREATEST(1,(SELECT COALESCE(max(id),1) FROM audit)))");await audit(c,req.user,null,'Backup restored','backup',{}, {createdAt:b.createdAt});});}catch(e){for(const file of writes)await fs.unlink(file).catch(()=>{});throw e;}res.json({ok:true});});
async function notify(tenderId,user,event,title,message,channels=[]){const id=randomUUID();const r=await pool.query('INSERT INTO notifications(id,tender_id,user_id,event_key,title,message) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING RETURNING id',[id,tenderId,user.id,event+':'+user.id,title,message]);if(!r.rowCount)return;for(const channel of channels)await pool.query('INSERT INTO deliveries(id,notification_id,channel,status) VALUES($1,$2,$3,$4)',[randomUUID(),id,channel,channel==='email'&&!process.env.SMTP_HOST||channel==='whatsapp'&&(!process.env.WHATSAPP_TOKEN||!process.env.WHATSAPP_PHONE_ID||!process.env.WHATSAPP_TEMPLATE||!user.phone)?'Not configured':'Queued']);}
let reminderRunning=false;
async function runReminders(){if(reminderRunning)return;reminderRunning=true;try{if(bdmsEnabled())await syncDirectory(pool);const config=await settings();const users=(await pool.query('SELECT * FROM users WHERE active=true')).rows;const tenders=(await pool.query('SELECT * FROM tenders WHERE draft=false')).rows;const allRecords=(await pool.query('SELECT * FROM records')).rows;const now=new Date();for(const t of tenders){const records=allRecords.filter(r=>r.tender_id===t.id);const calc=classify(t,records,config,now);const eligible=users.filter(u=>!u.business_unit||u.business_unit===t.data.businessUnit);if(calc.status==='Pending'&&calc.deadlineUtc){const minutes=(new Date(calc.deadlineUtc)-now)/60000;for(const offset of config.reminderOffsets){if(minutes<=offset&&minutes>0){const hours=offset/60;const roles=config.notificationRecipients[String(offset)]||['Bid Manager','BU Head'];for(const u of eligible.filter(u=>u.name===t.data.owner||u.roles.some(r=>roles.includes(r))))await notify(t.id,u,`deadline:${t.id}:${calc.deadlineUtc}:${offset}`,`${t.tender_id} · Deadline approaching`,`${t.data.title}: submission closes within ${hours>=24?hours/24+' days':hours+' hours'}.`,['whatsapp']);}}}if(calc.notAppliedReason==='Deadline Missed')for(const u of eligible.filter(u=>u.name===t.data.owner||u.roles.includes('BU Head')))await notify(t.id,u,`missed:${t.id}:${calc.deadlineUtc}`,`${t.tender_id} · Deadline missed`,t.data.title,['whatsapp']);if(t.data.deadlineChangedAt&&Date.now()-new Date(t.data.deadlineChangedAt)<172800000)for(const u of eligible.filter(u=>u.name===t.data.owner||u.roles.includes('Bid Manager')))await notify(t.id,u,`extension:${t.id}:${t.data.deadlineChangedAt}`,`${t.tender_id} · Deadline revised`,`New closing date: ${t.data.deadline} ${t.data.submissionTime}.`);
 for(const inst of records.filter(r=>r.module==='instruments'&&['Active','Extended'].includes(r.data.status))){const days=(new Date(inst.data.expiryDate)-now)/86400000;if(days<=config.instrumentReminderDays)for(const u of eligible.filter(u=>u.roles.includes('Finance / Treasury')||u.name===t.data.owner))await notify(t.id,u,`instrument:${inst.id}:${inst.data.expiryDate}`,`${t.tender_id} · Instrument expiry`,`${inst.data.reference} expires ${inst.data.expiryDate}.`,['email']);}}
 const pending=(await pool.query("SELECT a.*,t.tender_id AS ref,t.data FROM approvals a JOIN tenders t ON t.id=a.tender_id WHERE a.status='Pending'")).rows;for(const a of pending)for(const u of users.filter(u=>permitted(cleanUser(u),a.module,'approve',config)&&(!u.business_unit||u.business_unit===a.data.businessUnit)))await notify(a.tender_id,u,`approval:${a.id}`,`${a.ref} · Approval requested`,`${MODULES[a.module]?.label||a.module} is ready for review.`,['email']);
 const decided=(await pool.query("SELECT a.*,t.tender_id AS ref FROM approvals a JOIN tenders t ON t.id=a.tender_id WHERE a.status<>'Pending'")).rows;for(const a of decided){const u=users.find(u=>u.id===a.requested_by);if(u)await notify(a.tender_id,u,`decision:${a.id}`,`${a.ref} · ${a.module} ${a.status.toLowerCase()}`,a.comment||'Your approval request has been reviewed.');}
 const feed=(await pool.query('SELECT * FROM portal_feed')).rows;for(const p of feed)if(!tenders.some(t=>t.data.clientRef?.toLowerCase()===p.data.clientRef?.toLowerCase()&&t.data.client?.toLowerCase()===p.data.client?.toLowerCase()))for(const u of users.filter(u=>u.roles.some(r=>['BD Executive','Bid Manager'].includes(r))))await notify(null,u,`portal:${p.id}`,'Portal tender not registered',p.data.title);
 const queued=(await pool.query("SELECT d.*,n.title,n.message,COALESCE(u.contact_email,u.email) AS email,u.phone FROM deliveries d JOIN notifications n ON n.id=d.notification_id JOIN users u ON u.id=n.user_id WHERE d.status='Queued' AND d.next_attempt<=now() AND u.active=true LIMIT 20")).rows;for(const d of queued){try{if(d.channel==='email'){const transport=nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||587),secure:process.env.SMTP_SECURE==='true',auth:process.env.SMTP_USER?{user:process.env.SMTP_USER,pass:process.env.SMTP_PASSWORD}:undefined});await transport.sendMail({from:process.env.SMTP_FROM,to:d.email,subject:d.title,text:d.message});}else {if(!d.phone)throw new Error('Recipient WhatsApp phone number is missing.');const response=await fetch(`https://graph.facebook.com/${process.env.WHATSAPP_GRAPH_VERSION||'v23.0'}/${process.env.WHATSAPP_PHONE_ID}/messages`,{method:'POST',headers:{Authorization:'Bearer '+process.env.WHATSAPP_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({messaging_product:'whatsapp',to:d.phone.replace(/[^0-9]/g,''),type:'template',template:{name:process.env.WHATSAPP_TEMPLATE,language:{code:process.env.WHATSAPP_LANGUAGE||'en'},components:[{type:'body',parameters:[{type:'text',text:d.title},{type:'text',text:d.message}]}]}}),signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('WhatsApp delivery rejected: '+(await response.text()).slice(0,300));}await pool.query("UPDATE deliveries SET status='Sent',attempts=attempts+1 WHERE id=$1",[d.id]);}catch(e){await pool.query("UPDATE deliveries SET status=$1,error=$2,attempts=attempts+1,next_attempt=now()+interval '10 minutes' WHERE id=$3",[d.attempts>=2?'Failed':'Queued',e.message,d.id]);}}
 }catch(e){console.error('Reminder worker:',e.message);}finally{reminderRunning=false;}}
setInterval(runReminders,30000).unref();
app.post('/api/admin/run-reminders',async(req,res)=>{if(!isAdmin(req))throw fail(403,'Administrator access required.');await runReminders();res.json({ok:true});});
if(existsSync('dist/index.html')){app.use(express.static('dist',{maxAge:'1h'}));app.get('/{*path}',(req,res,next)=>req.path.startsWith('/api/')?next(fail(404,'API route not found.')):res.sendFile(path.resolve('dist/index.html')));}else{const {createServer}=await import('vite');const vite=await createServer({server:{middlewareMode:true},appType:'spa'});app.use(vite.middlewares);}
app.use((err,req,res,next)=>{console.error(err.status?err.message:err);if(res.headersSent)return next(err);let status=err.status||500,message=err.message;if(err.code==='23505'){status=409;message='This Tender ID, client reference, master value or pending approval already exists.';}if(err.code==='22P02'){status=400;message='Invalid record identifier.';}if(err instanceof multer.MulterError){status=422;message='File upload failed: '+err.message;}res.status(status).json({error:status===500?'The request could not be completed. Please try again.':message,fields:err.fields});});
const server=app.listen(PORT,runtime.host,()=>{console.log(`Tender Tracker ready: http://localhost:${PORT}`);console.log(`PostgreSQL data: ${process.env.TENDER_DATA_DIR||'Local AppData / TenderTracker / postgres'}`);runReminders();});
async function shutdown(){server.close();await pool.end();if(embedded)await embedded.stop();process.exit(0);}process.on('SIGINT',shutdown);process.on('SIGTERM',shutdown);
